// Public keys only. Each entry is a modulus, as `openssl rsa -modulus`
// prints it, and the text `adb keygen` wrote for the same key: the first
// field of its .pub file. A Python encoder of the libcrypto_utils
// structure (len, n0inv, n, rr = 2^4096 mod n, e) gives the same text.

enum AdbKeyVectors {
    static let all: [(modulusHex: String, base64: String)] = [
        (
            modulusHex: "",
            base64: ""
        ),
        (
            modulusHex: "",
            base64: ""
        ),
        (
            modulusHex: "",
            base64: ""
        ),
    ]
}
